import { classify, outside, interval } from './andregrad-svar.js';
const key='matematikkverksted-1t-andregrad-v1';
const app=document.querySelector('#app');
const initial={stage:'intro',history:[],hints:0,example:false,attempts:0,done:false,question:0,due:0};
let state=read();
function read(){try{return {...initial,history:[],...JSON.parse(localStorage.getItem(key)||'{}')}}catch{return {...initial}}}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{}}
function set(patch){state={...state,...patch};save();render()}
function share(result,variant,assisted=false){
  try{
    const ledgerKey='matematikkverksted-1t-oving-v1';
    const data=JSON.parse(localStorage.getItem(ledgerKey)||'{}');
    const logg=Array.isArray(data.logg)?data.logg:[];
    const ref='pilot-andregrad-'+variant;
    const row={id:'andregrad/3',ref,variant,nivaa:1,riktig:result,
      hint:assisted?Math.max(1,state.hints):0,forsok:variant==='prototype'&&state.route==='example'?0:1,tid:Date.now(),feil:result?'':'Fortegn og intervaller'};
    const index=logg.findIndex(item=>item.ref===ref);
    if(index>=0){
      const previous=logg[index];
      row.hint=Math.max(row.hint,previous.hint);
      row.forsok=previous.forsok+row.forsok;
      logg[index]=row;
    }else logg.push(row);
    localStorage.setItem(ledgerKey,JSON.stringify({...data,logg}));
  }catch{}
}
function clearShared(){
  try{
    const ledgerKey='matematikkverksted-1t-oving-v1';
    const data=JSON.parse(localStorage.getItem(ledgerKey)||'{}');
    if(!Array.isArray(data.logg))return;
    data.logg=data.logg.filter(row=>!String(row.ref).startsWith('pilot-andregrad-'));
    localStorage.setItem(ledgerKey,JSON.stringify(data));
  }catch{}
}

function graph(){let points=[];for(let i=-4;i<=4;i+=.1){let y=(i-2)*(i+3);points.push(`${60+(i+4)*65},${205-y*8}`)}return `<svg class="graph" viewBox="0 0 600 270" role="img" aria-label="Parabel med nullpunkter x lik minus tre og x lik to. Grafen ligger under x-aksen mellom nullpunktene"><path d="M 60 205 H 580 M 320 12 V 266" stroke="#899fb3" stroke-width="2"/><polyline points="${points.join(' ')}" fill="none" stroke="#2462a3" stroke-width="3"/><path d="M 125 205 H 450" stroke="#d45f35" stroke-width="5" stroke-dasharray="0 0"/><circle cx="125" cy="205" r="6" fill="#184d84"/><circle cx="450" cy="205" r="6" fill="#184d84"/><text x="335" y="25">y</text><text x="104" y="228">−3</text><text x="444" y="228">2</text><text x="560" y="227">x</text></svg>`}
function normalize(s){return s.trim().toLowerCase().replace(/[−–]/g,'-').replace(/≤/g,'<=').replace(/≥/g,'>=').replace(/\s+/g,'').replace(/\u221e/g,'inf')}
function nav(){return `<div class="stepper" aria-label="Framdrift">${['Start','Forkunnskap','Utforsk','Øv','Sjekk'].map((s,i)=>`<span class="${(['intro','diagnostic','explore','practice','check'].indexOf(state.stage)===i?'current':'')}">${s}</span>`).join('')}</div>`}
function scaffold(){return `<details><summary>Kort forklaring</summary><p>Et produkt er negativt når faktorene har ulike fortegn. Nullpunktene deler tallinja i intervaller. Test ett tall i hvert intervall.</p></details><details id="example"><summary>Gjennomregnet eksempel</summary><p>Løs (x − 1)(x + 2) &lt; 0.</p><ol><li>Nullpunktene er −2 og 1.</li><li>Ved x = 0 er produktet (−1) · 2 = −2.</li><li>Produktet er negativt mellom nullpunktene. Svaret er −2 &lt; x &lt; 1.</li></ol></details><details><summary>Fullfør mellomsteget</summary><p>For (x − 2)(x + 3): Ved x = 0 blir produktet (−2) · 3 = ____. Er tallet positivt eller negativt?</p></details>`}
function showIntro(){return `<h1>Fra faktorer til graf og ulikhet</h1><p class="lead">Undersøk hvorfor nullpunktene deler tallinja, og bruk fortegn til å løse en andregradsulikhet. Du kan gå direkte til oppgaven eller undersøke forkunnskapene først.</p><div class="card"><h2>Velg start</h2><button data-stage="practice">Gå rett til oppgaven</button><button class="secondary" data-stage="diagnostic">Ta forkunnskapssjekk</button><button class="secondary" data-stage="explore">Se sammenhengen i grafen</button>${state.history.length?'<button class="secondary" data-resume>Fortsett der jeg slapp</button>':''}</div>${teacher()}`}
function diagnostic(){return `<h1>Forkunnskapssjekk</h1><p class="lead">Finn nullpunktene til f(x) = (x − 2)(x + 3). Hva må minst én faktor være i et nullpunkt?</p><div class="card"><label for="diag">Skriv de to nullpunktene</label><input id="diag" placeholder="Skriv to tall"><button data-diagnostic>Se respons</button><div class="feedback" role="status" id="diag-feedback">${state.diagFeedback||'Svarene brukes som et startpunkt, ikke en karakter.'}</div><button class="secondary" data-stage="explore">Utforsk grafen</button><button class="secondary" data-stage="practice">Gå til oppgaven</button></div>`}
function explore(){return `<h1>Se sammenhengen</h1><p class="lead">Grafen viser f(x) = (x − 2)(x + 3). Den skjærer x-aksen ved −3 og 2. Hvor ligger grafen under x-aksen?</p><div class="card">${graph()}<p>Velg en testverdi i hvert av de tre intervallene. Sammenlikn fortegnet på faktorene med grafens plassering.</p><label for="test-x">Testverdi x</label><input id="test-x" type="range" min="-4" max="4" step="0.5" value="0"><p id="test-result" aria-live="polite">x = 0 gir (−2) · 3 = −6.</p><button data-stage="practice">Prøv ulikheten selv</button></div>`}
function feedback(){switch(state.route){case 'roots':return `<div class="feedback warning" role="status"><strong>Du fant nullpunktene −3 og 2.</strong> Hva blir produktet når x = 0, og hva forteller fortegnet deg?<label for="probe">Skriv produktet ved x = 0</label><input id="probe" inputmode="numeric" placeholder="Skriv produktet"><button data-probe="roots">Undersøk intervallet</button>${state.probeFeedback?`<p>${state.probeFeedback}</p>`:''}<p>Prøv deretter den opprinnelige oppgaven igjen.</p></div>`;case 'endpoints':return `<div class="feedback warning" role="status"><strong>Sjekk grenseverdiene.</strong> Sett inn x = 2. Oppfyller produktet kravet i oppgaven?<label for="probe">Hva blir produktet ved x = 2?</label><input id="probe" inputmode="numeric" placeholder="Skriv produktet"><button data-probe="endpoints">Undersøk endepunktene</button>${state.probeFeedback?`<p>${state.probeFeedback}</p>`:''}<p>Vurder begge endepunktene og prøv igjen.</p></div>`;case 'reason':return `<div class="feedback" role="status">Intervallet stemmer. Begrunn fortegnet med en testverdi mellom nullpunktene før du går videre.</div>`;case 'success':return `<div class="feedback success" role="status"><strong>Riktig og begrunnet.</strong> Mellom −3 og 2 er produktet negativt. Nå prøver du en variant med negativ koeffisient.</div>`;case 'example':return `<div class="feedback" role="status">Les fortegnene trinnvis. Løs så en ny oppgave på egen hånd før du vurderer mestring.</div>`;case 'unknown':return `<div class="feedback warning" role="status">Jeg kan ikke tolke svaret sikkert. Skriv en ulikhet med x eller bruk intervallparenteser.</div>`;default:return ''}}
function practice(){return `<h1>Løs en andregradsulikhet</h1><div class="grid"><div class="card"><p class="task formula">Løs (x − 2)(x + 3) &lt; 0.</p><p>Finn alle x-verdier som oppfyller ulikheten.</p><form id="answer"><label for="value">Svar som intervall eller ulikhet</label><input id="value" value="${escape(state.raw||'')}" placeholder="Bruk x og ulikhetstegn" required><label for="reason">Hvilken påstand begrunner fortegnet mellom nullpunktene?</label><select id="reason"><option value="">Velg en begrunnelse</option><option value="negative" ${state.reason==='negative'?'selected':''}>Ved x = 0 blir produktet −6, som er negativt.</option><option value="zero" ${state.reason==='zero'?'selected':''}>Ved x = 0 blir produktet 0.</option><option value="positive" ${state.reason==='positive'?'selected':''}>Ved x = 0 blir produktet 6, som er positivt.</option></select><button>Kontroller svaret</button></form>${feedback()}<button class="secondary" data-hint>Få hint</button><button class="secondary" data-example>Gå gjennom løsningen</button>${state.hints?`<div class="feedback">${state.hints===1?'Start med likningene x − 2 = 0 og x + 3 = 0.':'Prøv x = 0 mellom nullpunktene. Produktet blir −6.'}</div>`:''}${state.example?solution()+'<button data-stage="challenge">Prøv en ny oppgave selvstendig</button>':''}</div><aside class="card"><h2>Støtte underveis</h2>${scaffold()}<p class="student-note">Du bestemmer selv hvor mye støtte du bruker. Et svar etter hint gir grunnlag for videre øving. En ny selvstendig oppgave kan vise mestring.</p><button class="secondary" data-stage="explore">Se grafen</button></aside></div>`}
function solution(){return `<div class="feedback"><strong>Fortegn trinn for trinn</strong><ol><li>Faktorene er null ved x = −3 og x = 2.</li><li>Til venstre for −3 er begge faktorer negative, produktet positivt.</li><li>Mellom −3 og 2 er faktorene negative og positive, produktet negativt.</li><li>Til høyre for 2 er begge positive, produktet positivt.</li><li>Ved endepunktene er produktet 0. Streng ulikhet utelukker begge. Løsningen er −3 &lt; x &lt; 2.</li></ol></div>`}
function challenge(){let supported=state.route==='example'||state.hints>0;return `<h1>${supported?'Ny oppgave på egen hånd':'Større utfordring'}</h1><div class="grid"><div class="card">${!supported && state.route==='success'?'<div class="feedback success" role="status">Riktig og begrunnet. Du fant intervallet og viste at produktet er negativt mellom nullpunktene.</div>':''}<p class="task formula">${supported?'Løs (x − 1)(x + 4) < 0.':'Løs −(x − 1)(x + 4) < 0.'}</p><p>${supported?'Bruk nullpunktene og fortegnet mellom dem.':'Bruk både fortegn og grafens plassering. Løsningen består av to intervaller.'}</p><form id="challenge"><label for="challenge-answer">Svar</label><input id="challenge-answer" placeholder="Bruk x og ulikhetstegn" required><button>Sjekk svar</button></form>${state.challengeFeedback?`<div class="feedback ${state.done?'success':'warning'}" role="status">${state.challengeFeedback}</div>`:''}<button class="secondary" data-stage="practice">Mer støtte</button><button class="secondary" data-stage="explore">Gjennomgå den første grafen</button></div><aside class="card"><h2>Hva trenger du nå?</h2><p>${supported?'Denne kontrolloppgaven er ny. Et selvstendig svar sier mer om hva du kan enn løsningen du nettopp så.':'Når koeffisienten foran produktet er negativ, snur grafen. Undersøk hvor produktet ligger under null.'}</p></aside></div>`}
function check(){return `<h1>Din mestringssjekk</h1><div class="card"><p>${state.done?(state.retried?'Du løste kontrolloppgaven etter en ny gjennomgang.':'Du løste en ny oppgave selvstendig.'):'Prøv en ny variant selvstendig for å undersøke mestring.'}</p><ul class="checks"><li>Nullpunkter: ${state.history.some(o=>['roots','success','endpoints'].includes(o.route))?'observert':'for lite grunnlag'}</li><li>Fortegn og intervaller: ${state.done?(state.retried?'riktig etter nytt forsøk':'selvstendig på ny oppgave'):'for lite grunnlag'}</li><li>Støtte: ${state.example?'løsningsforslag sett':state.worked?'eksempel brukt':state.hints?'hint brukt':'ingen registrert'}</li></ul><p class="student-note">Progresjonen lagres bare i denne nettleseren.</p><a class="button" href="./index.html#tren/andregrad/3">Prøv flere nye varianter</a><button class="secondary" data-reset>Nullstill min progresjon</button></div>${teacher()}`}
function teacher(){return `<details class="card"><summary>Lærervisning og 45-minutters økt</summary><p>Del <code>${location.href.split('#')[0]}#oppgave</code> for å starte direkte på ulikheten. Elevene kan velge støtte underveis.</p><ol><li>0–5 min: Nullpunkter og fortegn i felles start.</li><li>5–12 min: Elevene velger forkunnskapssjekk eller går rett til oppgaven.</li><li>12–30 min: Individuelt arbeid, respons på feil og ny variant.</li><li>30–40 min: Elevene forklarer sammenhengen mellom produktets fortegn og grafens plassering.</li><li>40–45 min: Oppsummer hvorfor nullpunktene utelates ved en streng ulikhet, og hvorfor negativ koeffisient endrer løsningsmengden.</li></ol><p>Forkunnskaper: løse lineære likninger og kjenne faktorer. Typiske feil: bare nullpunkter, lukkede endepunkter, snudd fortegn. Spør: «Hvordan kan én testverdi avgjøre fortegnet i et intervall?»</p></details>`}
function escape(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){app.innerHTML=nav()+({intro:showIntro,diagnostic,explore,practice,challenge,check}[state.stage]||showIntro)();document.querySelector('#main').focus?.({preventScroll:true})}
function record(route){state.history.push({route,hints:state.hints,example:state.example,at:Date.now()});state.route=route;state.probeFeedback='';state.attempts++;share(route==='success','prototype',state.hints>0||state.example||route==='example');save()}
app.addEventListener('click',e=>{const t=e.target.closest('[data-stage],[data-reset],[data-resume],[data-hint],[data-example],[data-diagnostic],[data-probe]');if(!t)return;if(t.dataset.stage){if(t.dataset.stage==='explore')state.hints=Math.max(1,state.hints);set({stage:t.dataset.stage});return}if(t.hasAttribute('data-reset')){state={...initial,history:[]};clearShared();save();render();return}if(t.hasAttribute('data-resume')){set({stage:state.done?'check':'practice'});return}if(t.hasAttribute('data-hint')){set({hints:Math.min(state.hints+1,2)});return}if(t.hasAttribute('data-example')){record('example');set({example:true,stage:'practice'});return}if(t.hasAttribute('data-diagnostic')){set({diagFeedback:classify(app.querySelector('#diag').value)==='roots'?'Riktig: −3 og 2. Undersøk nå fortegnet mellom nullpunktene.':'Prøv å sette hver faktor lik null: x − 2 = 0 og x + 3 = 0.'});return}if(t.dataset.probe){const v=normalize(app.querySelector('#probe').value);set({probeFeedback:t.dataset.probe==='roots'?(v==='-6'?'Riktig. Produktet er negativt mellom nullpunktene. Skriv nå intervallet.':'Sett inn x = 0 i begge faktorene og gang tallene.'):v==='0'?'Riktig. 0 er ikke mindre enn 0. Det samme gjelder x = −3.':'Sett x = 2 inn i den første faktoren.'});return}});
app.addEventListener('toggle', e=>{
  if(e.target.open && e.target.tagName==='DETAILS' && state.stage==='practice'){
    state.hints=Math.max(1,state.hints);
    if(e.target.id==='example')state.worked=true;
    save();
  }
},true);
app.addEventListener('input',e=>{if(e.target.id==='test-x'){
  const x=Number(e.target.value), format=n=>n.toLocaleString('nb-NO');
  app.querySelector('#test-result').textContent='x = '+format(x)+' gir ('+format(x-2)+') · ('+format(x+3)+') = '+format((x-2)*(x+3))+'.';
  return;
}if(e.target.id==='value')state.raw=e.target.value;if(e.target.id==='reason')state.reason=e.target.value;save()});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='answer'){const route=classify(app.querySelector('#value').value);if(route==='correct'){const sound=app.querySelector('#reason').value==='negative';record(sound?'success':'reason');set({stage:sound?'challenge':'practice'});}else{record(route);render()}return}if(e.target.id==='challenge'){let raw=app.querySelector('#challenge-answer').value;const supported=state.route==='example'||state.hints>0;const right=supported?interval(raw,-4,1):outside(raw);share(right,supported?'fresh-supported':'fresh-stretch',false);const retried=state.challengeFeedback && !state.done;set({done:right,retried:Boolean(retried),challengeFeedback:right?'Riktig. Du har løst en ny variant selvstendig.':'Kontroller fortegnet på hver side av nullpunktene. Prøv igjen.',stage:right?'check':'challenge'});}});
if(location.hash==='#oppgave')state.stage='practice';render();

globalThis.window?.addEventListener('storage',event=>{
  if(event.key==='matematikkverksted-1t-gjenopprettet') location.reload();
});
